-- KINDS OF WORK: how each kind is built (Tony ruling 2026-11-11 08:47Z, correcting 08:34Z ruling 5).
--   backing = command : every step is a named bridge command.
--   backing = recipe  : a sequence of direct Revit calls sent through the bridge general-purpose commands. It has run on a real project;
--                       the receipts (project, script, what was checked) are stored with the kind. Fewer safety checks than a named command.
--   backing = unmapped: no named command and no recipe that has run.
-- surface.ceiling was wrongly recorded as a gap: ceilings were built on Deubner and Whitaker by a recipe. It locks.
-- casework.counter, site.fence, structure.resize also have recipes that ran: they lock. site.pool has neither: unmapped, draft.
-- structure.stairs stays draft; the stair recipe found is recorded, not adopted. Nothing existing is removed.

alter table public.intent_kinds add column if not exists backing text not null default 'command';
alter table public.intent_kinds drop constraint if exists intent_kinds_backing_check;
alter table public.intent_kinds add constraint intent_kinds_backing_check check (backing in ('command','recipe','unmapped'));
alter table public.intent_kinds add column if not exists recipe jsonb;

update public.intent_kinds set backing = 'recipe', recipe = $v${"summary": "One ceiling per room, drawn from the room's outline with Revit's own ceiling call, then set to its height.", "calls": ["Autodesk.Revit.DB.Ceiling.Create(doc, loops, ceilingTypeId, levelId)", "set_parameter_value: Height Offset From Level"], "receipts": [{"project": "Whitaker", "script": "exports/whitaker/s8a_ceilings.py", "date": "2026-11-09", "check": "build phase P8A done: 28 ceilings, height measured on every one"}, {"project": "Deubner", "script": "exports/deubner/c1c.py", "date": "2026-11-06", "check": "24 ceilings in the run record, none failed; size and height read back for each"}], "proven": true, "proven_note": null}$v$::jsonb, status_note = $v$The bridge has no named ceiling command. The recipe calls Revit directly, so it has fewer safety checks than a named command.$v$, status = 'locked', bridge_commands = $v$["revit.invoke_method", "revit.set_parameter_value"]$v$::jsonb, locked_build = 'f98f724', locked_at = '2026-11-11T08:55:00Z' where kind = 'surface.ceiling';
update public.intent_kinds set backing = 'recipe', recipe = $v${"summary": "A slab-only counter family is built in the family editor (box pieces, sink cutouts, material set on every face), then loaded and placed.", "calls": ["family editor through invoke_method: new family document, extrusion geometry, material parameter, SaveAs", "place_family_instance"], "receipts": [{"project": "Whitaker", "script": "exports/whitaker/s6_counters.py (library exports/whitaker/fb2.py)", "date": "2026-11-08", "check": "build phase P6A done: 16 slab families; phase P6B: 11 sinks pass the cutout check, model check 0 red"}], "proven": true, "proven_note": null}$v$::jsonb, status_note = $v$The named box command (create_family_box) has never been run. The recipe is what has been used.$v$, status = 'locked', bridge_commands = $v$["revit.invoke_method", "revit.place_family_instance", "revit.create_family_box"]$v$::jsonb, locked_build = 'f98f724', locked_at = '2026-11-11T08:55:00Z' where kind = 'casework.counter';
update public.intent_kinds set backing = 'recipe', recipe = $v${"summary": "Two ways. On a flat pad: a fence wall type (a copy of a curtain wall type) drawn along the line, posts from the type. On open ground: a railing drawn along the line and hosted on the terrain so it follows the ground.", "calls": ["Autodesk.Revit.DB.Wall.Create(doc, line, wallTypeId, levelId, height, offset, flip, structural)", "Autodesk.Revit.DB.Architecture.Railing.Create(doc, curveLoop, railingTypeId, levelId), then HostId set to the toposolid"], "receipts": [{"project": "Patel", "script": "exports/patel/tc_16.py", "date": "2026-11-10", "check": "3 fence runs, 15 ft; position and height measured by the script, then saved. Not a build-phase check"}, {"project": "693 Rancho", "script": "exports/rr_fence.py", "date": "2026-11-05", "check": "property-line fence created and following the terrain (size read back). Not a build-phase check"}], "proven": false, "proven_note": "ran and was measured by its own script; never passed a build-phase check"}$v$::jsonb, status_note = $v$Two recipes have run. Neither went through a build-phase check; each was measured by its own script.$v$, status = 'locked', bridge_commands = $v$["revit.invoke_method", "revit.duplicate_family_type"]$v$::jsonb, locked_build = 'f98f724', locked_at = '2026-11-11T08:55:00Z' where kind = 'site.fence';
update public.intent_kinds set backing = 'recipe', recipe = $v${"summary": "Move a whole wall (joined walls follow), or move one end: switch the end join off, set the wall's line, switch the join back on. Then move the edges that did not follow.", "calls": ["move_element", "WallUtils.DisallowWallJoinAtEnd -> LocationCurve.set_Curve -> WallUtils.AllowWallJoinAtEnd", "CurveElement.SetGeometryCurve for roof / ceiling / floor sketch lines (exports/patel/sk_lib.py)"], "receipts": [{"project": "Patel", "script": "exports/patel/p1b.py, exports/patel/p1c.py", "date": "2026-11-09", "check": "everything north of grid 1 moved 2 ft, saved; wall end, roof eave, ceiling edge and foundation edge corrected after. Not a build-phase check"}, {"project": "Patel", "script": "projects/patel/MICHAEL_FEEDBACK_1110B.md (S9 note; script not pinned)", "date": "2026-11-10", "check": "hall wall moved exactly 2.0 ft, centreline measured, joined walls followed, saved. Not a build-phase check"}, {"project": "Whitaker", "script": "exports/whitaker/split_fix3.py", "date": "2026-11-09", "check": "6 walls shortened and rejoined, length measured; the unjoin left 4 doors covered by stone, repaired by stone_fix.py"}], "proven": false, "proven_note": "ran and was measured by its own script; never passed a build-phase check; one run caused a defect that was repaired"}$v$::jsonb, status_note = $v$A person still decides what moves. Roof, ceiling, floor and foundation edges that do not follow the wall are moved line by line. One run broke stone cuts at doors and had to be repaired.$v$, status = 'locked', bridge_commands = $v$["revit.invoke_method", "revit.move_element"]$v$::jsonb, locked_build = 'f98f724', locked_at = '2026-11-11T08:55:00Z' where kind = 'structure.resize';
update public.intent_kinds set backing = 'unmapped', recipe = null, status_note = $v$Draft: no command and no recipe has built a pool. The two commands listed are an untested guess.$v$, status = 'draft' where kind = 'site.pool';
update public.intent_kinds set backing = 'command', recipe = $v${"summary": "Not adopted. Change an existing stair inside one stair edit: remove the landings, set each run's start and end height, move the runs, rebuild the landings, commit.", "calls": ["StairsEditScope Start / Commit", "reflect_set BaseElevation / TopElevation on each run", "ElementTransformUtils.MoveElement", "StairsLanding.CreateAutomaticLanding", "all in one batch_execute"], "receipts": [{"project": "Patel", "script": "exports/patel/ls_11.py", "date": "2026-11-11", "check": "west stair rebuilt to 27 risers (11 / 8 / 8), saved. Not a build-phase check"}], "proven": false, "proven_note": "ran once on an existing stair; never passed a build-phase check"}$v$::jsonb, status_note = $v$Draft: the bridge can create a stair but has no command that changes a stair run or its path. A recipe changed a stair run on Patel; it is recorded, not adopted.$v$, status = 'draft' where kind = 'structure.stairs';
